from collections.abc import Iterator
from datetime import date
from typing import Any

from pydantic import Field

from snowfall.vendor.junction_one.models import autogenerated


class Response(autogenerated.BaseModel):
    status: autogenerated.ResponseStatus | None = None
    code: int | None = None
    error: str | None = None
    data: dict[str, Any] = Field({})


class TripCreateRequest(autogenerated.BaseModel):
    name: str
    org_id: int
    arranger_ids: list[int] | None = None
    booker_ids: list[int] | None = None
    visibility: autogenerated.VisibilityType | None = None
    start_date: date | None = None
    end_date: date | None = None
    notify: bool | None = None
    text: str | None = None


class TripCreateRefsRequest(autogenerated.BaseModel):
    name: str | None
    arranger_ids: list[int] | None = None
    booker_ids: list[int] | None = None
    visibility: autogenerated.VisibilityType | None = None
    car_refs: str | None = None
    flight_refs: str | None = None
    hotel_refs: str | None = None
    train_refs: str | None = None
    notify: bool | None = None


class TripboardCreateRequest(autogenerated.BaseModel):
    trip_id: int
    booker_id: int


class HotelDetailsRequest(autogenerated.BaseModel):
    refs: list[str]


class TripListRequest(autogenerated.BaseModel):
    user_id: int | None = None


class TripDeleteRequest(autogenerated.BaseModel):
    id: int


class GetTripRequest(autogenerated.BaseModel):
    trip_id: int


class AddRefsRequest(autogenerated.BaseModel):
    id: int
    trip_id: int
    hotel_refs: str | None


class AddFopRequest(autogenerated.BaseModel):
    tripboard_ref_id: int
    card_id: int


class TripboardProcessRequest(autogenerated.BaseModel):
    id: int
    flag: autogenerated.TripBoardProcessingFlags


class UpdateReservationFieldRequest(autogenerated.BaseModel):
    reservation_id: int
    field_id: int
    field_value_id: int
    remark: str | None


class UpdateReservationRequest(autogenerated.BaseModel):
    id: int
    currency: str | None = None
    flags: int | None = None
    label: str | None = None
    not_in_policy_reason: str | None = Field(None, alias="notInPolicyReason")
    not_preferred_reason: str | None = Field(None, alias="notPreferredReason")
    org_project_id: int | None = Field(None, alias="orgProjectId")
    status: autogenerated.ReservationStatus | None = None
    total_price: float | None = Field(None, alias="totalPrice")
    angency_pnr: str | None = None
    vendor_pnr: str | None = Field(None, alias="vendorPnr")
    start_date: autogenerated.AwareOrNaiveDatetime | None = Field(
        None,
        alias="startDate",
    )
    end_date: autogenerated.AwareOrNaiveDatetime | None = Field(None, alias="endDate")
    user_ids: list[int] = Field(alias="userIds", default_factory=list)
    inf: int | None = None
    ext: autogenerated.IsReservationExt | None = None
    rlk: str | None = None


class SeatType(autogenerated.BaseModel):
    name: str
    level: int
    price_from: float | None = Field(None, alias="priceFrom")
    price_to: float | None = Field(None, alias="priceTo")
    available_seats: int | None = Field(None, alias="availableSeats")


class SeatMapSegment(autogenerated.SeatMapSegment):
    seat_types: dict[str, SeatType] = Field(alias="seatTypes")  # type: ignore[assignment]

    def seats(self) -> Iterator[autogenerated.SeatMapSeat]:
        for cabin in self.cabins:
            for row in cabin.rows:
                yield from row.seats


class FlightSeatMapResponse(autogenerated.FlightSeatMapResponse):
    segments: list[SeatMapSegment]  # type: ignore[assignment]
